// Lenient filter parsing implementation
// Filter condition fields accept null, single-object, or array forms
// This is by-design for backward compatibility and user convenience
pub fn parse_filter_condition(input: Option<Value>) -> Result<Filter> {
    match input {
        None => Ok(Filter::default()), // null treated as no-filter
        Some(value) => parse_filter_value(value), // single-object or array
    }
}

